private static final class IdName {

  private String id;
  private String name;
}

private IdName parseIdName(final JsonIterator ji) {
  final var p = new IdName();
  ji.testObject(ID_NAME_FIELDS, (field, ji1) -> {
    switch (field) {
      case 0 -> p.id = ji1.readString();
      case 1 -> p.name = ji1.readString();
      default -> ji1.skip();
    }
    return true;
  });
  return p;
}
